INSERT INTO content_strings (id, section, key, value_en, value_de) VALUES (gen_random_uuid(), 'app', 'dashboard.carousel.addMeasurementDesc', 'Track your latest readings. The more data you add, the smarter your insights become.', 'Erfasse deine neuesten Werte. Je mehr Daten du hinzufügst, desto klüger werden deine Einblicke.') ON CONFLICT (section, key) DO NOTHING;
