INSERT INTO content_strings (id, section, key, value_en, value_de) VALUES (gen_random_uuid(), 'app', 'dashboard.carousel.askDoctorDesc', 'Got questions about your markers? Our AI doctor analyzes your data and gives personalized insights.', 'Fragen zu deinen Markern? Unser KI-Arzt analysiert deine Daten und gibt personalisierte Einblicke.') ON CONFLICT (section, key) DO NOTHING;
