INSERT INTO content_strings (id, section, key, value_en, value_de) VALUES (gen_random_uuid(), 'app', 'dashboard.carousel.didYouKnowDesc', 'Your body recycles 95% of its iron every day. Explore fascinating facts about your biomarkers.', 'Dein Körper recycelt 95% seines Eisens jeden Tag. Entdecke faszinierende Fakten über deine Biomarker.') ON CONFLICT (section, key) DO NOTHING;
