INSERT INTO content_strings (id, section, key, value_en, value_de) VALUES (gen_random_uuid(), 'app', 'dashboard.carousel.exploreTrendsDesc', 'See how your markers change over time. Compare periods and spot patterns.', 'Sieh, wie sich deine Marker über die Zeit verändern. Vergleiche Zeiträume und erkenne Muster.') ON CONFLICT (section, key) DO NOTHING;
