INSERT INTO content_strings (id, section, key, value_en, value_de) VALUES (gen_random_uuid(), 'app', 'dashboard.carousel.gkiRatioDesc', 'Glucose-Ketone Index shows your metabolic flexibility. Lower is better for fat adaptation.', 'Der Glukose-Keton-Index zeigt deine metabolische Flexibilität. Niedriger ist besser für die Fettadaption.') ON CONFLICT (section, key) DO NOTHING;
INSERT INTO content_strings (id, section, key, value_en, value_de) VALUES (gen_random_uuid(), 'app', 'dashboard.carousel.healthZones', 'Understanding Health Zones', 'Gesundheitszonen verstehen') ON CONFLICT (section, key) DO NOTHING;
INSERT INTO content_strings (id, section, key, value_en, value_de) VALUES (gen_random_uuid(), 'app', 'dashboard.carousel.healthZonesDesc', 'Learn what each zone means and why these markers matter for your health.', 'Erfahre, was jede Zone bedeutet und warum diese Marker für deine Gesundheit wichtig sind.') ON CONFLICT (section, key) DO NOTHING;
