INSERT INTO content_strings (id, section, key, value_en, value_de) VALUES (gen_random_uuid(), 'app', 'doctorChat.agents.diet', 'Based on my current marker data and any borderline or red values, recommend specific foods and dietary changes that could help improve my numbers. Consider my current diet protocol.', 'Empfiehl basierend auf meinen aktuellen Markerdaten und grenzwertigen oder roten Werten bestimmte Lebensmittel und Ernährungsänderungen, die meine Werte verbessern könnten. Berücksichtige mein aktuelles Ernährungsprotokoll.') ON CONFLICT (section, key) DO NOTHING;
INSERT INTO content_strings (id, section, key, value_en, value_de) VALUES (gen_random_uuid(), 'app', 'doctorChat.agents.labs', 'Explain my latest lab results in plain language. Go through each marker, explain what it means, whether my level is optimal, and what actions I should consider.', 'Erkläre meine neuesten Laborergebnisse in einfacher Sprache. Gehe jeden Marker durch, erkläre seine Bedeutung, ob mein Wert optimal ist und welche Maßnahmen ich in Betracht ziehen sollte.') ON CONFLICT (section, key) DO NOTHING;
INSERT INTO content_strings (id, section, key, value_en, value_de) VALUES (gen_random_uuid(), 'app', 'doctorChat.agents.protocols', 'Compare my health markers across different diet protocols I have followed. How did switching between carnivore, keto, fasting, or other protocols affect my numbers?', 'Vergleiche meine Gesundheitsmarker über verschiedene Ernährungsprotokolle, denen ich gefolgt bin. Wie hat sich der Wechsel zwischen Karnivor, Keto, Fasten oder anderen Protokollen auf meine Werte ausgewirkt?') ON CONFLICT (section, key) DO NOTHING;
INSERT INTO content_strings (id, section, key, value_en, value_de) VALUES (gen_random_uuid(), 'app', 'doctorChat.agents.supplements', 'Review my current supplement stack against my marker data. Are my supplements working? Are there gaps I should address? Check for any interaction concerns.', 'Prüfe meine aktuelle Nahrungsergänzung gegen meine Markerdaten. Wirken meine Supplements? Gibt es Lücken? Prüfe auf Wechselwirkungen.') ON CONFLICT (section, key) DO NOTHING;
INSERT INTO content_strings (id, section, key, value_en, value_de) VALUES (gen_random_uuid(), 'app', 'doctorChat.agents.trends', 'Analyze my health marker trends over the last 60 days. Identify improvements, areas of concern, and any correlations between markers. Focus on actionable insights.', 'Analysiere meine Gesundheitsmarker-Trends der letzten 60 Tage. Identifiziere Verbesserungen, Bereiche mit Handlungsbedarf und Korrelationen zwischen Markern. Konzentriere dich auf umsetzbare Erkenntnisse.') ON CONFLICT (section, key) DO NOTHING;
INSERT INTO content_strings (id, section, key, value_en, value_de) VALUES (gen_random_uuid(), 'app', 'doctorChat.analyzingDocument', 'Analyzing your document...', 'Dokument wird analysiert...') ON CONFLICT (section, key) DO NOTHING;
