INSERT INTO content_strings (id, section, key, value_en, value_de) VALUES (gen_random_uuid(), 'app', 'zones.cardiovascular', 'How strong is your heart and circulation? This zone focuses on true cardiovascular risk through particle count (ApoB), blood pressure, and lipid ratios.', 'Wie stark ist dein Herz und Kreislauf? Diese Zone konzentriert sich auf das tatsächliche kardiovaskuläre Risiko durch Partikelanzahl (ApoB), Blutdruck und Lipidverhältnisse.') ON CONFLICT (section, key) DO NOTHING;
