INSERT INTO content_strings (id, section, key, value_en, value_de) VALUES (gen_random_uuid(), 'app', 'zones.cognitive', 'Is your brain sharp, memory clear, and mood stable? B vitamins, magnesium, thyroid hormones, and sex hormones directly impact cognition.', 'Ist dein Gehirn scharf, Gedächtnis klar und Stimmung stabil? B-Vitamine, Magnesium, Schilddrüsenhormone und Geschlechtshormone beeinflussen die Kognition direkt.') ON CONFLICT (section, key) DO NOTHING;
