INSERT INTO content_strings (id, section, key, value_en, value_de) VALUES (gen_random_uuid(), 'app', 'zones.detoxification', 'Can your body efficiently process and eliminate waste? Your liver and kidneys are the filtration system.', 'Kann dein Körper Abfallstoffe effizient verarbeiten und eliminieren? Leber und Nieren sind das Filtrationssystem.') ON CONFLICT (section, key) DO NOTHING;
