INSERT INTO content_strings (id, section, key, value_en, value_de) VALUES (gen_random_uuid(), 'app', 'zones.energy', 'Can you sustain energy throughout the day without crashes? This zone tracks your glucose, insulin, ketones, and thyroid function.', 'Kannst du den ganzen Tag Energie halten, ohne Einbrüche? Diese Zone verfolgt Glukose, Insulin, Ketone und Schilddrüsenfunktion.') ON CONFLICT (section, key) DO NOTHING;
