INSERT INTO content_strings (id, section, key, value_en, value_de) VALUES (gen_random_uuid(), 'app', 'zones.hormonal', 'Are your hormones optimized for your age? Sex hormones and stress hormones orchestrate metabolism, mood, libido, and recovery.', 'Sind deine Hormone für dein Alter optimiert? Geschlechts- und Stresshormone steuern Stoffwechsel, Stimmung, Libido und Erholung.') ON CONFLICT (section, key) DO NOTHING;
