INSERT INTO content_strings (id, section, key, value_en, value_de) VALUES (gen_random_uuid(), 'web', 'drAlexChat.quickQuestions', '[''What is ApoB and why does it matter?'', "Carnivore vs Keto — what''s the difference?", ''What plan is right for me?'', ''How do health zones work?'', ''Can I self-host this?'', "What''s the GKI and why track it?"]', '[''Was ist ApoB und warum ist es wichtig?'', ''Karnivore vs. Keto – was ist der Unterschied?'', ''Welcher Tarif passt zu mir?'', ''Wie funktionieren die Gesundheitszonen?'', ''Kann ich das selbst hosten?'', ''Was ist der GKI und warum sollte man ihn erfassen?'']') ON CONFLICT (section, key) DO NOTHING;
