INSERT INTO content_strings (id, section, key, value_en, value_de) VALUES (gen_random_uuid(), 'web', 'features.categories.comingSoon.allergySensitivityTracker.description', 'Record your allergies and sensitivities. See how allergy seasons and trigger foods correlate with your inflammatory markers like hs-CRP. Turn guesswork into data.', 'Erfassen Sie Ihre Allergien und Empfindlichkeiten. Sehen Sie, wie Allergiesaisons und auslösende Lebensmittel mit Ihren Entzündungsmarkern wie hs-CRP korrelieren. Verwandeln Sie Vermutungen in Daten.') ON CONFLICT (section, key) DO NOTHING;
