INSERT INTO content_strings (id, section, key, value_en, value_de) VALUES (gen_random_uuid(), 'web', 'features.categories.comingSoon.foodIntelligence.description', 'See what your body actually absorbs, not just what''s on the label. Flags anti-nutrients like oxalates and phytates that block mineral absorption. Smarter food choices for your protocol.', 'Sehen Sie, was Ihr Körper tatsächlich aufnimmt, nicht nur was auf dem Etikett steht. Kennzeichnet Anti-Nährstoffe wie Oxalate und Phytate, die die Mineralstoffaufnahme blockieren. Klügere Lebensmittelauswahl für Ihr Protokoll.') ON CONFLICT (section, key) DO NOTHING;
