INSERT INTO content_strings (id, section, key, value_en, value_de) VALUES (gen_random_uuid(), 'web', 'features.categories.trackYourHealth.medicationImport.description', 'Photo of supplement bottles. Identified and logged automatically.', 'Foto von Nahrungsergänzungsmittel-Packungen. Automatisch erkannt und protokolliert.') ON CONFLICT (section, key) DO NOTHING;
INSERT INTO content_strings (id, section, key, value_en, value_de) VALUES (gen_random_uuid(), 'web', 'features.categories.trackYourHealth.medicationImport.name', 'Medication Import', 'Medikamenten-Import') ON CONFLICT (section, key) DO NOTHING;
INSERT INTO content_strings (id, section, key, value_en, value_de) VALUES (gen_random_uuid(), 'web', 'features.categories.trackYourHealth.recordDailyMeasurements.description', 'Log your blood markers in seconds. Build a template for your routine tests so you only see the markers you care about. Whether you use a Fora 6, Qardio smart scale, or get lab work done, everything goes into one secure place.', 'Protokollieren Sie Ihre Blutmarker in Sekundenschnelle. Erstellen Sie eine Vorlage für Ihre Routineuntersuchungen, damit Sie nur die Marker sehen, die Ihnen wichtig sind. Ob Sie ein Fora 6, eine Qardio-Smartwaage oder Laborwerte verwenden – alles landet an einem sicheren Ort.') ON CONFLICT (section, key) DO NOTHING;
INSERT INTO content_strings (id, section, key, value_en, value_de) VALUES (gen_random_uuid(), 'web', 'features.categories.trackYourHealth.recordDailyMeasurements.name', 'Record Daily Measurements', 'Tägliche Messungen erfassen') ON CONFLICT (section, key) DO NOTHING;
INSERT INTO content_strings (id, section, key, value_en, value_de) VALUES (gen_random_uuid(), 'web', 'features.categories.trackYourHealth.supportedDevices.description', 'Works with home testing devices like the Fora 6 multi-parameter meter (glucose, ketones, cholesterol, uric acid, hemoglobin, hematocrit), Qardio Arm blood pressure monitor, Qardiobase 2 smart scale (weight, body fat, muscle mass, water, bone mass), and any lab provider. You can also add your own devices and define what they measure.', 'Funktioniert mit Heimtestgeräten wie dem Fora 6 Multiparameter-Messgerät (Glukose, Ketone, Cholesterin, Harnsäure, Hämoglobin, Hämatokrit), dem Qardio Arm Blutdruckmessgerät, der Qardiobase 2 Smartwaage (Gewicht, Körperfett, Muskelmasse, Wasseranteil, Knochenmasse) und jedem Laboranbieter. Sie können auch eigene Geräte hinzufügen und festlegen, was sie messen.') ON CONFLICT (section, key) DO NOTHING;
INSERT INTO content_strings (id, section, key, value_en, value_de) VALUES (gen_random_uuid(), 'web', 'features.categories.trackYourHealth.supportedDevices.name', 'Supported Devices', 'Unterstützte Geräte') ON CONFLICT (section, key) DO NOTHING;
INSERT INTO content_strings (id, section, key, value_en, value_de) VALUES (gen_random_uuid(), 'web', 'features.categories.understandYourNumbers.fastingImpact.description', '22 markers have fasting-specific reference ranges with explanations. Understand why your glucose drops, ketones rise, and uric acid increases during a fast.', '22 Marker haben fastenspezifische Referenzbereiche mit Erklärungen. Verstehen Sie, warum Ihr Blutzucker sinkt, Ketone steigen und Harnsäure während des Fastens zunimmt.') ON CONFLICT (section, key) DO NOTHING;
INSERT INTO content_strings (id, section, key, value_en, value_de) VALUES (gen_random_uuid(), 'web', 'features.categories.understandYourNumbers.fastingImpact.name', 'Fasting Impact', 'Fastenauswirkung') ON CONFLICT (section, key) DO NOTHING;
INSERT INTO content_strings (id, section, key, value_en, value_de) VALUES (gen_random_uuid(), 'web', 'features.categories.understandYourNumbers.foodRecommendations.description', 'See which foods can help improve each marker. From grass-fed beef and salmon to blueberries and dark chocolate, organized by category with explanations.', 'Sehen Sie, welche Lebensmittel zur Verbesserung jedes Markers beitragen können. Von Weidehaltungs-Rindfleisch und Lachs bis hin zu Blaubeeren und dunkler Schokolade, nach Kategorien geordnet mit Erklärungen.') ON CONFLICT (section, key) DO NOTHING;
INSERT INTO content_strings (id, section, key, value_en, value_de) VALUES (gen_random_uuid(), 'web', 'features.categories.understandYourNumbers.foodRecommendations.name', 'Food Recommendations', 'Ernährungsempfehlungen') ON CONFLICT (section, key) DO NOTHING;
INSERT INTO content_strings (id, section, key, value_en, value_de) VALUES (gen_random_uuid(), 'web', 'features.categories.understandYourNumbers.heading', 'Understand Your Numbers', 'Ihre Werte verstehen') ON CONFLICT (section, key) DO NOTHING;
INSERT INTO content_strings (id, section, key, value_en, value_de) VALUES (gen_random_uuid(), 'web', 'features.categories.understandYourNumbers.markerDetailPages.description', 'Every marker has a dedicated page that explains what it measures and why it matters. Written in plain language that anyone can understand.', 'Jeder Marker hat eine eigene Seite, die erklärt, was er misst und warum er wichtig ist. In verständlicher Sprache geschrieben, die jeder verstehen kann.') ON CONFLICT (section, key) DO NOTHING;
INSERT INTO content_strings (id, section, key, value_en, value_de) VALUES (gen_random_uuid(), 'web', 'features.categories.understandYourNumbers.markerDetailPages.name', 'Marker Detail Pages', 'Marker-Detailseiten') ON CONFLICT (section, key) DO NOTHING;
INSERT INTO content_strings (id, section, key, value_en, value_de) VALUES (gen_random_uuid(), 'web', 'features.categories.understandYourNumbers.markerRelationships.description', 'See how your markers connect to each other. Over 30 documented relationships help you see the bigger picture.', 'Sehen Sie, wie Ihre Marker miteinander zusammenhängen. Über 30 dokumentierte Beziehungen helfen Ihnen, das Gesamtbild zu sehen.') ON CONFLICT (section, key) DO NOTHING;
INSERT INTO content_strings (id, section, key, value_en, value_de) VALUES (gen_random_uuid(), 'web', 'features.categories.understandYourNumbers.markerRelationships.name', 'Marker Relationships', 'Marker-Zusammenhänge') ON CONFLICT (section, key) DO NOTHING;
INSERT INTO content_strings (id, section, key, value_en, value_de) VALUES (gen_random_uuid(), 'web', 'features.categories.understandYourNumbers.protocolGuides.description', 'What happens to your markers on carnivore? How does keto affect your insulin? Six diet protocols mapped against 20+ markers.', 'Was passiert mit Ihren Markern bei der Karnivoren-Diät? Wie beeinflusst Keto Ihr Insulin? Sechs Ernährungsprotokolle abgebildet auf über 20 Marker.') ON CONFLICT (section, key) DO NOTHING;
INSERT INTO content_strings (id, section, key, value_en, value_de) VALUES (gen_random_uuid(), 'web', 'features.categories.understandYourNumbers.protocolGuides.name', 'Protocol Guides', 'Protokoll-Leitfäden') ON CONFLICT (section, key) DO NOTHING;
INSERT INTO content_strings (id, section, key, value_en, value_de) VALUES (gen_random_uuid(), 'web', 'features.categories.understandYourNumbers.supplementGuidance.description', 'Evidence-based supplement suggestions for each marker. Includes typical dosage ranges, timing tips, and how each supplement affects your numbers.', 'Evidenzbasierte Empfehlungen für Nahrungsergänzungsmittel zu jedem Marker. Einschließlich typischer Dosierungsbereiche, Einnahmehinweise und wie jedes Ergänzungsmittel Ihre Werte beeinflusst.') ON CONFLICT (section, key) DO NOTHING;
INSERT INTO content_strings (id, section, key, value_en, value_de) VALUES (gen_random_uuid(), 'web', 'features.categories.understandYourNumbers.supplementGuidance.name', 'Supplement Guidance', 'Nahrungsergänzungsmittel-Ratgeber') ON CONFLICT (section, key) DO NOTHING;
