INSERT INTO content_strings (id, section, key, value_en, value_de) VALUES (gen_random_uuid(), 'web', 'healthZones.zones.energyMetabolic.description', 'Blood sugar, insulin, ketones, and the markers that determine how your body produces and uses energy. Essential for anyone tracking fasting, keto, or carnivore protocols.', 'Blutzucker, Insulin, Ketone und die Marker, die bestimmen, wie Ihr Körper Energie produziert und nutzt. Unverzichtbar für alle, die Fasten-, Keto- oder Karnivore-Protokolle verfolgen.') ON CONFLICT (section, key) DO NOTHING;
