INSERT INTO content_strings (id, section, key, value_en, value_de) VALUES (gen_random_uuid(), 'web', 'home.features.encrypted.description', 'AES-256 encryption at rest. Zero-knowledge design. Even we cannot read your health data. No tracking, no cookies, no analytics.', 'AES-256-Verschlüsselung im Ruhezustand. Zero-Knowledge-Design. Selbst wir können Ihre Gesundheitsdaten nicht lesen. Kein Tracking, keine Cookies, keine Analytik.') ON CONFLICT (section, key) DO NOTHING;
