INSERT INTO content_strings (id, section, key, value_en, value_de) VALUES (gen_random_uuid(), 'web', 'home.sections.securityPrivacy', 'Security & Privacy', 'Sicherheit & Datenschutz') ON CONFLICT (section, key) DO NOTHING;
INSERT INTO content_strings (id, section, key, value_en, value_de) VALUES (gen_random_uuid(), 'web', 'home.sections.viewAll', 'View all', 'Alle anzeigen') ON CONFLICT (section, key) DO NOTHING;
INSERT INTO content_strings (id, section, key, value_en, value_de) VALUES (gen_random_uuid(), 'web', 'home.securityDescriptions.aes256', 'All health data is encrypted at rest using AES-256, the same standard used by banks and governments.', 'Alle Gesundheitsdaten werden mit AES-256 verschlüsselt gespeichert, dem gleichen Standard wie bei Banken und Regierungen.') ON CONFLICT (section, key) DO NOTHING;
INSERT INTO content_strings (id, section, key, value_en, value_de) VALUES (gen_random_uuid(), 'web', 'home.securityDescriptions.gdpr', 'Fully GDPR and ePrivacy compliant. Your data stays in your control with full export and deletion rights.', 'Vollständig DSGVO- und ePrivacy-konform. Ihre Daten bleiben unter Ihrer Kontrolle mit vollständigen Export- und Löschrechten.') ON CONFLICT (section, key) DO NOTHING;
INSERT INTO content_strings (id, section, key, value_en, value_de) VALUES (gen_random_uuid(), 'web', 'home.securityDescriptions.noTracking', 'No cookies, no analytics, no tracking pixels. We don''t monitor your behavior or sell your data.', 'Keine Cookies, keine Analytik, keine Tracking-Pixel. Wir überwachen Ihr Verhalten nicht und verkaufen Ihre Daten nicht.') ON CONFLICT (section, key) DO NOTHING;
INSERT INTO content_strings (id, section, key, value_en, value_de) VALUES (gen_random_uuid(), 'web', 'home.securityDescriptions.openSource', 'Our core is AGPL-3.0 licensed. Audit the code yourself, or self-host for complete independence.', 'Unser Kern ist AGPL-3.0-lizenziert. Prüfen Sie den Code selbst oder hosten Sie selbst für vollständige Unabhängigkeit.') ON CONFLICT (section, key) DO NOTHING;
INSERT INTO content_strings (id, section, key, value_en, value_de) VALUES (gen_random_uuid(), 'web', 'home.securityDescriptions.tls13', 'All data in transit is protected with TLS 1.3, ensuring secure communication between you and our servers.', 'Alle Daten während der Übertragung sind mit TLS 1.3 geschützt, was eine sichere Kommunikation zwischen Ihnen und unseren Servern gewährleistet.') ON CONFLICT (section, key) DO NOTHING;
INSERT INTO content_strings (id, section, key, value_en, value_de) VALUES (gen_random_uuid(), 'web', 'home.securityDescriptions.zeroKnowledge', 'We cannot read your health data. Your measurements are encrypted before they reach our servers.', 'Wir können Ihre Gesundheitsdaten nicht lesen. Ihre Messungen werden verschlüsselt, bevor sie unsere Server erreichen.') ON CONFLICT (section, key) DO NOTHING;
