INSERT INTO content_strings (id, section, key, value_en, value_de) VALUES (gen_random_uuid(), 'web', 'impressum.applicableLaw.text', 'Austrian law applies to this website and service, in particular the Austrian E-Commerce Act (E-Commerce-Gesetz, ECG) and the Austrian Media Act (MedienG).', 'Auf diese Website und diesen Dienst findet österreichisches Recht Anwendung, insbesondere das österreichische E-Commerce-Gesetz (ECG) und das österreichische Mediengesetz (MedienG).') ON CONFLICT (section, key) DO NOTHING;
