INSERT INTO content_strings (id, section, key, value_en, value_de) VALUES (gen_random_uuid(), 'web', 'impressum.contentResponsibility.text', 'Helmut Schindlwick, as the operator of this website, is responsible for the content pursuant to Section 55(2) of the Austrian Broadcasting Agreement (RStV).', 'Helmut Schindlwick ist als Betreiber dieser Website gemäß § 55 Abs. 2 des Rundfunkstaatsvertrags (RStV) für den Inhalt verantwortlich.') ON CONFLICT (section, key) DO NOTHING;
INSERT INTO content_strings (id, section, key, value_en, value_de) VALUES (gen_random_uuid(), 'web', 'impressum.disputeResolution.heading', 'EU Online Dispute Resolution', 'EU-Online-Streitbeilegung') ON CONFLICT (section, key) DO NOTHING;
INSERT INTO content_strings (id, section, key, value_en, value_de) VALUES (gen_random_uuid(), 'web', 'impressum.disputeResolution.paragraph1', 'The European Commission provides a platform for online dispute resolution (ODR) for consumers. This platform is available at:', 'Die Europäische Kommission stellt eine Plattform zur Online-Streitbeilegung (OS) für Verbraucher bereit. Diese Plattform ist verfügbar unter:') ON CONFLICT (section, key) DO NOTHING;
INSERT INTO content_strings (id, section, key, value_en, value_de) VALUES (gen_random_uuid(), 'web', 'impressum.disputeResolution.paragraph2', 'If you are a consumer residing in the European Union, you may use this platform to submit a complaint regarding a product or service purchased online. We are committed to resolving any disputes through direct communication and will respond to any complaints received through the ODR platform promptly.', 'Wenn Sie ein Verbraucher mit Wohnsitz in der Europäischen Union sind, können Sie diese Plattform nutzen, um eine Beschwerde über ein online erworbenes Produkt oder eine Dienstleistung einzureichen. Wir sind bestrebt, etwaige Streitigkeiten durch direkte Kommunikation zu lösen, und werden auf Beschwerden, die über die OS-Plattform eingehen, umgehend reagieren.') ON CONFLICT (section, key) DO NOTHING;
