INSERT INTO content_strings (id, section, key, value_en, value_de) VALUES (gen_random_uuid(), 'web', 'openSource.quickStart.dockerNote', 'Requires Docker and Docker Compose. See the README for detailed setup instructions.', 'Erfordert Docker und Docker Compose. Siehe README für detaillierte Installationsanweisungen.') ON CONFLICT (section, key) DO NOTHING;
