INSERT INTO content_strings (id, section, key, value_en, value_de) VALUES (gen_random_uuid(), 'web', 'openSource.whatYouGet.features', '[''90+ health markers across 8 zones'', ''Trend analysis with reference ranges'', ''Fasting protocol adjustments'', ''Medication and supplement tracking'', ''Calculated health scores'', ''Full data export (CSV, JSON)'', ''AES-256 encryption at rest'', ''Dr. Alex AI (bring your own API key)'']', '[''Über 90 Gesundheitsmarker in 8 Zonen'', ''Trendanalyse mit Referenzbereichen'', ''Fastenprotokoll-Anpassungen'', ''Medikamenten- und Nahrungsergänzungsmittel-Tracking'', ''Berechnete Gesundheitswerte'', ''Vollständiger Datenexport (CSV, JSON)'', ''AES-256-Verschlüsselung im Ruhezustand'', ''Dr. Alex AI (eigener API-Schlüssel erforderlich)'']') ON CONFLICT (section, key) DO NOTHING;
INSERT INTO content_strings (id, section, key, value_en, value_de) VALUES (gen_random_uuid(), 'web', 'openSource.whatYouGet.heading', 'What You Get', 'Was Sie erhalten') ON CONFLICT (section, key) DO NOTHING;
INSERT INTO content_strings (id, section, key, value_en, value_de) VALUES (gen_random_uuid(), 'web', 'openSource.whyOpenSource.communityDriven.description', 'Built in the open with community input. Feature requests, bug reports, and pull requests are all welcome. Your voice shapes the roadmap.', 'Öffentlich entwickelt mit Community-Input. Funktionswünsche, Fehlermeldungen und Pull Requests sind willkommen. Ihre Stimme prägt die Roadmap.') ON CONFLICT (section, key) DO NOTHING;
INSERT INTO content_strings (id, section, key, value_en, value_de) VALUES (gen_random_uuid(), 'web', 'openSource.whyOpenSource.communityDriven.title', 'Community Driven', 'Community-getrieben') ON CONFLICT (section, key) DO NOTHING;
INSERT INTO content_strings (id, section, key, value_en, value_de) VALUES (gen_random_uuid(), 'web', 'openSource.whyOpenSource.dataSovereignty.description', 'Your health data lives on your server. No cloud dependency, no third-party access. You control the database, the backups, and who can see it.', 'Ihre Gesundheitsdaten liegen auf Ihrem Server. Keine Cloud-Abhängigkeit, kein Zugriff Dritter. Sie kontrollieren die Datenbank, die Backups und wer Zugang hat.') ON CONFLICT (section, key) DO NOTHING;
INSERT INTO content_strings (id, section, key, value_en, value_de) VALUES (gen_random_uuid(), 'web', 'openSource.whyOpenSource.dataSovereignty.title', 'Data Sovereignty', 'Datensouveränität') ON CONFLICT (section, key) DO NOTHING;
INSERT INTO content_strings (id, section, key, value_en, value_de) VALUES (gen_random_uuid(), 'web', 'openSource.whyOpenSource.fullTransparency.description', 'Every line of code is auditable. No hidden telemetry, no secret data collection, no obfuscated logic. What you see is what runs.', 'Jede Zeile Code ist überprüfbar. Keine versteckte Telemetrie, keine geheime Datenerfassung, keine verschleierte Logik. Was Sie sehen, ist das, was läuft.') ON CONFLICT (section, key) DO NOTHING;
INSERT INTO content_strings (id, section, key, value_en, value_de) VALUES (gen_random_uuid(), 'web', 'openSource.whyOpenSource.fullTransparency.title', 'Full Transparency', 'Vollständige Transparenz') ON CONFLICT (section, key) DO NOTHING;
INSERT INTO content_strings (id, section, key, value_en, value_de) VALUES (gen_random_uuid(), 'web', 'openSource.whyOpenSource.heading', 'Why Open Source Matters', 'Warum Open Source wichtig ist') ON CONFLICT (section, key) DO NOTHING;
INSERT INTO content_strings (id, section, key, value_en, value_de) VALUES (gen_random_uuid(), 'web', 'openSource.whyOpenSource.zeroTrust.description', 'AES-256 encryption at rest, TLS 1.3 in transit. Even the database stores encrypted values  - a compromised server reveals nothing.', 'AES-256-Verschlüsselung im Ruhezustand, TLS 1.3 bei der Übertragung. Selbst die Datenbank speichert verschlüsselte Werte – ein kompromittierter Server gibt nichts preis.') ON CONFLICT (section, key) DO NOTHING;
INSERT INTO content_strings (id, section, key, value_en, value_de) VALUES (gen_random_uuid(), 'web', 'openSource.whyOpenSource.zeroTrust.title', 'Zero Trust Architecture', 'Zero-Trust-Architektur') ON CONFLICT (section, key) DO NOTHING;
