INSERT INTO content_strings (id, section, key, value_en, value_de) VALUES (gen_random_uuid(), 'web', 'partners.affiliate.description', 'Share Sovereign Health with your network and earn 20% commission on every referred subscription. Every registered user is automatically an affiliate. No application needed. Ideal for health podcasters, nutrition coaches, carnivore and keto community leaders, and Bitcoin advocates who understand the value of data sovereignty.', 'Teile Sovereign Health mit deinem Netzwerk und verdiene 20% Provision auf jedes vermittelte Abonnement. Jeder registrierte Nutzer ist automatisch ein Affiliate. Keine Bewerbung noetig. Ideal fuer Gesundheits-Podcaster, Ernaehrungscoaches, Karnivore- und Keto-Community-Leiter und Bitcoin-Befuerworter, die den Wert von Datensouveraenitaet verstehen.') ON CONFLICT (section, key) DO NOTHING;
