INSERT INTO content_strings (id, section, key, value_en, value_de) VALUES (gen_random_uuid(), 'web', 'partners.hero.tagline', 'Better health outcomes through better partnerships.', 'Bessere Gesundheitsergebnisse durch bessere Partnerschaften.') ON CONFLICT (section, key) DO NOTHING;
INSERT INTO content_strings (id, section, key, value_en, value_de) VALUES (gen_random_uuid(), 'web', 'partners.hero.title', 'Partner With Us', 'Partner werden') ON CONFLICT (section, key) DO NOTHING;
INSERT INTO content_strings (id, section, key, value_en, value_de) VALUES (gen_random_uuid(), 'web', 'partners.types.contentContributors.description', 'Our knowledge base covers 90+ markers with plain-language descriptions, food recommendations, supplement guidance, and protocol effects. Medical professionals, nutritionists, and researchers can contribute to make it better. All contributions are open source, credited, and help thousands of users understand their health data. If you have expertise in metabolic health, we want to hear from you.', 'Unsere Wissensdatenbank deckt ueber 90 Marker mit verstaendlichen Beschreibungen, Ernaehrungsempfehlungen, Nahrungsergaenzungsmittel-Ratgebern und Protokollauswirkungen ab. Mediziner, Ernaehrungsberater und Forscher koennen dazu beitragen, sie zu verbessern. Alle Beitraege sind Open Source, werden namentlich genannt und helfen Tausenden von Nutzern, ihre Gesundheitsdaten zu verstehen. Wenn Sie Expertise im Bereich metabolischer Gesundheit haben, moechten wir von Ihnen hoeren.') ON CONFLICT (section, key) DO NOTHING;
INSERT INTO content_strings (id, section, key, value_en, value_de) VALUES (gen_random_uuid(), 'web', 'partners.types.contentContributors.title', 'Content and Knowledge Contributors', 'Inhalts- und Wissensmitwirkende') ON CONFLICT (section, key) DO NOTHING;
INSERT INTO content_strings (id, section, key, value_en, value_de) VALUES (gen_random_uuid(), 'web', 'partners.types.deviceManufacturers.description', 'Your hardware generates valuable health data. Make sure it reaches your customers in a platform they actually control. Sovereign Health supports open device integrations and gives users full ownership of their measurements. By partnering with us, your device becomes part of a privacy-first ecosystem that health-conscious users actively seek out. We handle the software, you handle the hardware.', 'Ihre Hardware erzeugt wertvolle Gesundheitsdaten. Stellen Sie sicher, dass sie Ihre Kunden auf einer Plattform erreichen, die sie tatsaechlich kontrollieren. Sovereign Health unterstuetzt offene Geraeteintegrationen und gibt Nutzern die volle Hoheit ueber ihre Messwerte. Durch eine Partnerschaft mit uns wird Ihr Geraet Teil eines datenschutzorientierten Oekosystems, das gesundheitsbewusste Nutzer aktiv suchen. Wir kuemmern uns um die Software, Sie um die Hardware.') ON CONFLICT (section, key) DO NOTHING;
INSERT INTO content_strings (id, section, key, value_en, value_de) VALUES (gen_random_uuid(), 'web', 'partners.types.deviceManufacturers.title', 'Device Manufacturers', 'Geraetehersteller') ON CONFLICT (section, key) DO NOTHING;
INSERT INTO content_strings (id, section, key, value_en, value_de) VALUES (gen_random_uuid(), 'web', 'partners.types.healthPractitioners.description', 'Your patients spend 99% of their time outside your office. Give them a tool to track blood markers, medications, and lifestyle changes between visits. When they come back, they bring real data instead of vague descriptions. Sovereign Health integrates with any lab provider and supports 90+ markers. Patients become active participants in their health journey, and you get better data to work with. The Horizon tier includes multi-patient oversight so you can monitor trends across your practice.', 'Ihre Patienten verbringen 99 % ihrer Zeit ausserhalb Ihrer Praxis. Geben Sie ihnen ein Werkzeug, um Blutmarker, Medikamente und Lebensstilaenderungen zwischen den Besuchen zu erfassen. Wenn sie zurueckkommen, bringen sie echte Daten statt vager Beschreibungen mit. Sovereign Health laesst sich mit jedem Laboranbieter integrieren und unterstuetzt ueber 90 Marker. Patienten werden zu aktiven Teilnehmern ihrer Gesundheitsreise, und Sie erhalten bessere Daten. Der Horizon-Tarif bietet Multi-Patienten-Uebersicht, damit Sie Trends in Ihrer Praxis beobachten koennen.') ON CONFLICT (section, key) DO NOTHING;
INSERT INTO content_strings (id, section, key, value_en, value_de) VALUES (gen_random_uuid(), 'web', 'partners.types.healthPractitioners.title', 'Health Practitioners', 'Gesundheitsfachkraefte') ON CONFLICT (section, key) DO NOTHING;
