INSERT INTO content_strings (id, section, key, value_en, value_de) VALUES (gen_random_uuid(), 'web', 'pricing.enterprise.description', 'Need multi-patient dashboards, team accounts, or custom integrations? Horizon+ is built for clinics, nutritionists, and health coaches who manage client health data.', 'Benötigen Sie Multi-Patienten-Dashboards, Teamkonten oder individuelle Integrationen? Horizon+ wurde für Kliniken, Ernährungsberater und Gesundheitscoaches entwickelt, die Gesundheitsdaten ihrer Klienten verwalten.') ON CONFLICT (section, key) DO NOTHING;
