INSERT INTO content_strings (id, section, key, value_en, value_de) VALUES (gen_random_uuid(), 'web', 'pricing.faq.items.cancelAnytime.answer', 'Yes. Cancel anytime from your account settings. Your data stays accessible at the free tier level. No cancellation fees, no questions asked.', 'Ja. Kündigen Sie jederzeit in Ihren Kontoeinstellungen. Ihre Daten bleiben auf dem kostenlosen Tariflevel zugänglich. Keine Kündigungsgebühren, keine Fragen.') ON CONFLICT (section, key) DO NOTHING;
INSERT INTO content_strings (id, section, key, value_en, value_de) VALUES (gen_random_uuid(), 'web', 'pricing.faq.items.cancelAnytime.question', 'Can I cancel anytime?', 'Kann ich jederzeit kündigen?') ON CONFLICT (section, key) DO NOTHING;
INSERT INTO content_strings (id, section, key, value_en, value_de) VALUES (gen_random_uuid(), 'web', 'pricing.faq.items.dataOwnership.answer', 'You do. Always. We never sell, share, or analyze your health data. You can export everything at any time and delete your account permanently.', 'Ihnen. Immer. Wir verkaufen, teilen oder analysieren Ihre Gesundheitsdaten niemals. Sie können jederzeit alles exportieren und Ihr Konto dauerhaft löschen.') ON CONFLICT (section, key) DO NOTHING;
INSERT INTO content_strings (id, section, key, value_en, value_de) VALUES (gen_random_uuid(), 'web', 'pricing.faq.items.dataOwnership.question', 'Who owns my data?', 'Wem gehören meine Daten?') ON CONFLICT (section, key) DO NOTHING;
INSERT INTO content_strings (id, section, key, value_en, value_de) VALUES (gen_random_uuid(), 'web', 'pricing.faq.items.freeTier.answer', 'Yes. Glimpse is free with no time limit and no credit card required. You get 15 markers, 90 days of history, and basic AI chat. It is a fully functional tier, not a trial.', 'Ja. Glimpse ist kostenlos, ohne Zeitlimit und ohne Kreditkarte. Sie erhalten 15 Marker, 90 Tage Verlauf und Basis-AI-Chat. Es handelt sich um einen voll funktionsfähigen Tarif, nicht um eine Testversion.') ON CONFLICT (section, key) DO NOTHING;
INSERT INTO content_strings (id, section, key, value_en, value_de) VALUES (gen_random_uuid(), 'web', 'pricing.faq.items.freeTier.question', 'Is the free tier really free forever?', 'Ist der kostenlose Tarif wirklich für immer kostenlos?') ON CONFLICT (section, key) DO NOTHING;
INSERT INTO content_strings (id, section, key, value_en, value_de) VALUES (gen_random_uuid(), 'web', 'pricing.faq.items.paymentMethods.answer', 'We will accept credit cards, debit cards, and SEPA direct debit via Stripe. All prices are in EUR. Payment processing is not yet live.', 'Wir werden Kreditkarten, Debitkarten und SEPA-Lastschrift über Stripe akzeptieren. Alle Preise sind in EUR. Die Zahlungsabwicklung ist noch nicht aktiv.') ON CONFLICT (section, key) DO NOTHING;
INSERT INTO content_strings (id, section, key, value_en, value_de) VALUES (gen_random_uuid(), 'web', 'pricing.faq.items.paymentMethods.question', 'What payment methods do you accept?', 'Welche Zahlungsmethoden akzeptieren Sie?') ON CONFLICT (section, key) DO NOTHING;
INSERT INTO content_strings (id, section, key, value_en, value_de) VALUES (gen_random_uuid(), 'web', 'pricing.faq.items.refundPolicy.answer', 'Full refund within 30 days of your first paid subscription, no questions asked. After 30 days, your subscription continues until the end of the billing period.', 'Volle Rückerstattung innerhalb von 30 Tagen nach Ihrem ersten kostenpflichtigen Abonnement, ohne Fragen. Nach 30 Tagen läuft Ihr Abonnement bis zum Ende des Abrechnungszeitraums weiter.') ON CONFLICT (section, key) DO NOTHING;
INSERT INTO content_strings (id, section, key, value_en, value_de) VALUES (gen_random_uuid(), 'web', 'pricing.faq.items.refundPolicy.question', 'What is your refund policy?', 'Was ist Ihre Rückerstattungsrichtlinie?') ON CONFLICT (section, key) DO NOTHING;
INSERT INTO content_strings (id, section, key, value_en, value_de) VALUES (gen_random_uuid(), 'web', 'pricing.faq.items.selfHost.answer', 'Yes. The open source core is free under AGPL-3.0. Run it on your own server with Docker. The Horizon tier adds a hybrid option that syncs a self-hosted instance with our cloud features.', 'Ja. Der Open Source Kern ist kostenlos unter AGPL-3.0. Betreiben Sie ihn auf Ihrem eigenen Server mit Docker. Der Horizon-Tarif bietet eine Hybridoption, die eine selbst gehostete Instanz mit unseren Cloud-Funktionen synchronisiert.') ON CONFLICT (section, key) DO NOTHING;
INSERT INTO content_strings (id, section, key, value_en, value_de) VALUES (gen_random_uuid(), 'web', 'pricing.faq.items.selfHost.question', 'Can I self-host instead?', 'Kann ich stattdessen selbst hosten?') ON CONFLICT (section, key) DO NOTHING;
INSERT INTO content_strings (id, section, key, value_en, value_de) VALUES (gen_random_uuid(), 'web', 'pricing.hero.subtitle', 'Start free. Upgrade when you need more. Every plan includes encryption, privacy, and full data ownership.', 'Starten Sie kostenlos. Upgraden Sie, wenn Sie mehr brauchen. Jeder Tarif beinhaltet Verschlüsselung, Datenschutz und volle Datenhoheit.') ON CONFLICT (section, key) DO NOTHING;
