INSERT INTO content_strings (id, section, key, value_en, value_de) VALUES (gen_random_uuid(), 'web', 'referral.howItWorks.steps.share.description', 'Share your link with friends, colleagues, or your community.', 'Teilen Sie Ihren Link mit Freunden, Kollegen oder Ihrer Community.') ON CONFLICT (section, key) DO NOTHING;
