INSERT INTO content_strings (id, section, key, value_en, value_de) VALUES (gen_random_uuid(), 'web', 'referral.howItWorks.steps.signUp.description', 'Create an account and subscribe to any plan.', 'Erstellen Sie ein Konto und abonnieren Sie einen beliebigen Plan.') ON CONFLICT (section, key) DO NOTHING;
