INSERT INTO content_strings (id, section, key, value_en, value_de) VALUES (gen_random_uuid(), 'web', 'referral.promoCodes.heading', 'Promo Codes & Referrals', 'Promo-Codes & Empfehlungen') ON CONFLICT (section, key) DO NOTHING;
INSERT INTO content_strings (id, section, key, value_en, value_de) VALUES (gen_random_uuid(), 'web', 'referral.promoCodes.items', '[''Promo codes give buyers a discount on their subscription.'', ''Promo discounts and referral commissions work independently.'', ''Affiliate commission is calculated on the discounted price.'']', '[''Promo-Codes geben Kaeufern einen Rabatt auf ihr Abonnement.'', ''Promo-Rabatte und Empfehlungsprovisionen funktionieren unabhaengig voneinander.'', ''Die Affiliate-Provision wird auf den rabattierten Preis berechnet.'']') ON CONFLICT (section, key) DO NOTHING;
INSERT INTO content_strings (id, section, key, value_en, value_de) VALUES (gen_random_uuid(), 'web', 'security.ai.aiAssisted.description', 'Dr. Alex provides AI-powered insights to help you understand your health data. All analysis is informational. The AI does not make decisions for you.', 'Dr. Alex bietet AI-gestuetzte Einblicke, um Ihnen zu helfen, Ihre Gesundheitsdaten zu verstehen. Alle Analysen sind informativ. Die AI trifft keine Entscheidungen fuer Sie.') ON CONFLICT (section, key) DO NOTHING;
INSERT INTO content_strings (id, section, key, value_en, value_de) VALUES (gen_random_uuid(), 'web', 'security.ai.aiAssisted.title', 'AI-Assisted, Not AI-Decided', 'AI-unterstuetzt, nicht AI-entschieden') ON CONFLICT (section, key) DO NOTHING;
INSERT INTO content_strings (id, section, key, value_en, value_de) VALUES (gen_random_uuid(), 'web', 'security.ai.heading', 'AI & Health Data', 'AI & Gesundheitsdaten') ON CONFLICT (section, key) DO NOTHING;
INSERT INTO content_strings (id, section, key, value_en, value_de) VALUES (gen_random_uuid(), 'web', 'security.ai.noAiTraining.description', 'AI queries are sent to Anthropic Claude with anonymized context only. Your name, email, and identifying information are never included. Your data is not used to train AI models.', 'AI-Anfragen werden an Anthropic Claude nur mit anonymisiertem Kontext gesendet. Ihr Name, Ihre E-Mail und identifizierende Informationen werden nie mitgesendet. Ihre Daten werden nicht zum Training von AI-Modellen verwendet.') ON CONFLICT (section, key) DO NOTHING;
INSERT INTO content_strings (id, section, key, value_en, value_de) VALUES (gen_random_uuid(), 'web', 'security.ai.noAiTraining.title', 'Your Data Does Not Train AI', 'Ihre Daten trainieren keine AI') ON CONFLICT (section, key) DO NOTHING;
INSERT INTO content_strings (id, section, key, value_en, value_de) VALUES (gen_random_uuid(), 'web', 'security.ai.noDataSharing.description', 'Your health data is never shared with third parties, never sold, and never used for advertising. This is a core architectural commitment, not a policy that can be changed.', 'Ihre Gesundheitsdaten werden nie an Dritte weitergegeben, nie verkauft und nie fuer Werbung verwendet. Dies ist eine architektonische Kernverpflichtung, keine aenderbare Richtlinie.') ON CONFLICT (section, key) DO NOTHING;
INSERT INTO content_strings (id, section, key, value_en, value_de) VALUES (gen_random_uuid(), 'web', 'security.ai.noDataSharing.title', 'Health Data Never Shared or Sold', 'Gesundheitsdaten werden nie geteilt oder verkauft') ON CONFLICT (section, key) DO NOTHING;
INSERT INTO content_strings (id, section, key, value_en, value_de) VALUES (gen_random_uuid(), 'web', 'security.ai.noMedicalAdvice.description', 'Sovereign Health Intelligence is not a medical device and does not provide medical advice. Always consult your doctor for medical decisions.', 'Sovereign Health Intelligence ist kein Medizinprodukt und bietet keine medizinische Beratung. Konsultieren Sie immer Ihren Arzt fuer medizinische Entscheidungen.') ON CONFLICT (section, key) DO NOTHING;
INSERT INTO content_strings (id, section, key, value_en, value_de) VALUES (gen_random_uuid(), 'web', 'security.ai.noMedicalAdvice.title', 'Not Medical Advice', 'Keine medizinische Beratung') ON CONFLICT (section, key) DO NOTHING;
INSERT INTO content_strings (id, section, key, value_en, value_de) VALUES (gen_random_uuid(), 'web', 'security.compliance.ageRequirement.description', 'The platform is intended for adults only. Accounts created by users under 18 will be deleted upon discovery.', 'Die Plattform ist nur fuer Erwachsene bestimmt. Konten, die von Nutzern unter 18 Jahren erstellt werden, werden bei Entdeckung geloescht.') ON CONFLICT (section, key) DO NOTHING;
INSERT INTO content_strings (id, section, key, value_en, value_de) VALUES (gen_random_uuid(), 'web', 'security.compliance.ageRequirement.title', '18+ Age Requirement', 'Mindestalter 18 Jahre') ON CONFLICT (section, key) DO NOTHING;
INSERT INTO content_strings (id, section, key, value_en, value_de) VALUES (gen_random_uuid(), 'web', 'security.compliance.austrianEcg.description', 'Operated under Austrian law with full legal disclosure per the Austrian E-Commerce Act (ECG). See our Impressum for complete details.', 'Betrieben nach oesterreichischem Recht mit vollstaendiger rechtlicher Offenlegung gemaess dem oesterreichischen E-Commerce-Gesetz (ECG). Siehe unser Impressum fuer vollstaendige Details.') ON CONFLICT (section, key) DO NOTHING;
INSERT INTO content_strings (id, section, key, value_en, value_de) VALUES (gen_random_uuid(), 'web', 'security.compliance.austrianEcg.title', 'Austrian ECG / Impressum', 'Oesterreichisches ECG / Impressum') ON CONFLICT (section, key) DO NOTHING;
INSERT INTO content_strings (id, section, key, value_en, value_de) VALUES (gen_random_uuid(), 'web', 'security.compliance.dataDeletion.description', 'Delete your account from Settings at any time. All data removed from the primary database within 30 days. Encrypted backups purged within 90 days.', 'Loeschen Sie Ihr Konto jederzeit in den Einstellungen. Alle Daten werden innerhalb von 30 Tagen aus der primaeren Datenbank entfernt. Verschluesselte Backups werden innerhalb von 90 Tagen bereinigt.') ON CONFLICT (section, key) DO NOTHING;
INSERT INTO content_strings (id, section, key, value_en, value_de) VALUES (gen_random_uuid(), 'web', 'security.compliance.dataDeletion.title', 'Data Deletion on Request', 'Datenloeschung auf Anfrage') ON CONFLICT (section, key) DO NOTHING;
INSERT INTO content_strings (id, section, key, value_en, value_de) VALUES (gen_random_uuid(), 'web', 'security.compliance.dataExport.description', 'Download your complete health history as JSON or CSV anytime from the application. Generate PDF health reports for your doctor.', 'Laden Sie Ihre gesamte Gesundheitshistorie jederzeit als JSON oder CSV aus der Anwendung herunter. Erstellen Sie PDF-Gesundheitsberichte fuer Ihren Arzt.') ON CONFLICT (section, key) DO NOTHING;
INSERT INTO content_strings (id, section, key, value_en, value_de) VALUES (gen_random_uuid(), 'web', 'security.compliance.dataExport.title', 'Full Data Export', 'Vollstaendiger Datenexport') ON CONFLICT (section, key) DO NOTHING;
INSERT INTO content_strings (id, section, key, value_en, value_de) VALUES (gen_random_uuid(), 'web', 'security.compliance.gdpr.description', 'Full compliance with the EU General Data Protection Regulation. Data stored in EU (Lithuania). Full data portability and right to erasure built into the platform.', 'Vollstaendige Einhaltung der EU-Datenschutz-Grundverordnung. Daten werden in der EU (Litauen) gespeichert. Vollstaendige Datenportabilitaet und Recht auf Loeschung sind in die Plattform integriert.') ON CONFLICT (section, key) DO NOTHING;
INSERT INTO content_strings (id, section, key, value_en, value_de) VALUES (gen_random_uuid(), 'web', 'security.compliance.gdpr.title', 'GDPR Compliant', 'DSGVO-konform') ON CONFLICT (section, key) DO NOTHING;
INSERT INTO content_strings (id, section, key, value_en, value_de) VALUES (gen_random_uuid(), 'web', 'security.compliance.heading', 'Compliance', 'Compliance') ON CONFLICT (section, key) DO NOTHING;
INSERT INTO content_strings (id, section, key, value_en, value_de) VALUES (gen_random_uuid(), 'web', 'security.compliance.refundPolicy.description', 'Full refund within 30 days of your first paid subscription, no questions asked. After 30 days, your subscription continues until the end of the billing period.', 'Vollstaendige Rueckerstattung innerhalb von 30 Tagen nach Ihrem ersten kostenpflichtigen Abonnement, ohne Fragen. Danach laeuft Ihr Abonnement bis zum Ende des Abrechnungszeitraums.') ON CONFLICT (section, key) DO NOTHING;
INSERT INTO content_strings (id, section, key, value_en, value_de) VALUES (gen_random_uuid(), 'web', 'security.compliance.refundPolicy.title', '30-Day Refund Policy', '30-Tage-Rueckerstattung') ON CONFLICT (section, key) DO NOTHING;
INSERT INTO content_strings (id, section, key, value_en, value_de) VALUES (gen_random_uuid(), 'web', 'security.contact.cta', 'Report Security Issue', 'Sicherheitsproblem melden') ON CONFLICT (section, key) DO NOTHING;
INSERT INTO content_strings (id, section, key, value_en, value_de) VALUES (gen_random_uuid(), 'web', 'security.contact.description', 'If you discover a security vulnerability, please report it responsibly. We take every report seriously and will respond promptly.', 'Wenn Sie eine Sicherheitsluecke entdecken, melden Sie diese bitte verantwortungsvoll. Wir nehmen jeden Bericht ernst und antworten zeitnah.') ON CONFLICT (section, key) DO NOTHING;
INSERT INTO content_strings (id, section, key, value_en, value_de) VALUES (gen_random_uuid(), 'web', 'security.contact.heading', 'Report a Security Issue', 'Sicherheitsproblem melden') ON CONFLICT (section, key) DO NOTHING;
INSERT INTO content_strings (id, section, key, value_en, value_de) VALUES (gen_random_uuid(), 'web', 'security.hero.tagline', 'Transparency builds trust. Here is exactly how we protect your data.', 'Transparenz schafft Vertrauen. So schuetzen wir Ihre Daten.') ON CONFLICT (section, key) DO NOTHING;
INSERT INTO content_strings (id, section, key, value_en, value_de) VALUES (gen_random_uuid(), 'web', 'security.hero.title', 'Security & Trust', 'Sicherheit & Vertrauen') ON CONFLICT (section, key) DO NOTHING;
INSERT INTO content_strings (id, section, key, value_en, value_de) VALUES (gen_random_uuid(), 'web', 'security.intro.paragraph1', 'Health data is among the most sensitive information a person can have. Where you store it, who can access it, and how it is protected are not minor details. They are the foundation of any health platform worth using.', 'Gesundheitsdaten gehoeren zu den sensibelsten Informationen, die eine Person haben kann. Wo sie gespeichert werden, wer darauf zugreifen kann und wie sie geschuetzt werden, sind keine Nebensaechlichkeiten. Sie sind das Fundament jeder Gesundheitsplattform, die es wert ist, genutzt zu werden.') ON CONFLICT (section, key) DO NOTHING;
INSERT INTO content_strings (id, section, key, value_en, value_de) VALUES (gen_random_uuid(), 'web', 'security.intro.paragraph2', 'Sovereign Health Intelligence was built from day one with a single architectural principle: we should not be able to read your health data, even if we wanted to. This is not a marketing claim. It is a technical decision baked into the code, which you can verify yourself because the source is open.', 'Sovereign Health Intelligence wurde von Anfang an mit einem einzigen architektonischen Prinzip gebaut: Wir sollten Ihre Gesundheitsdaten nicht lesen koennen, selbst wenn wir es wollten. Das ist kein Marketing-Versprechen. Es ist eine technische Entscheidung, die im Code verankert ist, den Sie selbst ueberpruefen koennen, weil der Quellcode offen ist.') ON CONFLICT (section, key) DO NOTHING;
INSERT INTO content_strings (id, section, key, value_en, value_de) VALUES (gen_random_uuid(), 'web', 'security.intro.paragraph3', 'This page explains our security approach in detail. Every claim made here is verifiable in the source code.', 'Diese Seite erklaert unseren Sicherheitsansatz im Detail. Jede hier gemachte Aussage ist im Quellcode ueberpruefbar.') ON CONFLICT (section, key) DO NOTHING;
INSERT INTO content_strings (id, section, key, value_en, value_de) VALUES (gen_random_uuid(), 'web', 'security.openSource.description', 'Our core technology is open source under the AGPL-3.0 license. The backend, frontend, and database schema are all publicly available. Community contributions are welcome. We believe that open source is the only way to build real trust in a health platform.', 'Unsere Kerntechnologie ist Open Source unter der AGPL-3.0-Lizenz. Backend, Frontend und Datenbankschema sind oeffentlich verfuegbar. Community-Beitraege sind willkommen. Wir glauben, dass Open Source der einzige Weg ist, echtes Vertrauen in eine Gesundheitsplattform aufzubauen.') ON CONFLICT (section, key) DO NOTHING;
INSERT INTO content_strings (id, section, key, value_en, value_de) VALUES (gen_random_uuid(), 'web', 'security.openSource.heading', 'Open Source Commitment', 'Open-Source-Verpflichtung') ON CONFLICT (section, key) DO NOTHING;
INSERT INTO content_strings (id, section, key, value_en, value_de) VALUES (gen_random_uuid(), 'web', 'security.openSource.link', 'View our open source projects', 'Unsere Open-Source-Projekte ansehen') ON CONFLICT (section, key) DO NOTHING;
INSERT INTO content_strings (id, section, key, value_en, value_de) VALUES (gen_random_uuid(), 'web', 'security.payment.bitcoinDiscount.description', 'Pay with Bitcoin for privacy-preserving payments and receive a 5% discount. Bitcoin payments do not require sharing personal financial information.', 'Zahlen Sie mit Bitcoin fuer datenschutzfreundliche Zahlungen und erhalten Sie 5% Rabatt. Bitcoin-Zahlungen erfordern keine Weitergabe persoenlicher Finanzinformationen.') ON CONFLICT (section, key) DO NOTHING;
INSERT INTO content_strings (id, section, key, value_en, value_de) VALUES (gen_random_uuid(), 'web', 'security.payment.bitcoinDiscount.title', '5% Bitcoin Discount', '5% Bitcoin-Rabatt') ON CONFLICT (section, key) DO NOTHING;
INSERT INTO content_strings (id, section, key, value_en, value_de) VALUES (gen_random_uuid(), 'web', 'security.payment.btcpay.description', 'Bitcoin payments are processed through our self-hosted BTCPay Server instance. No third-party payment processor involved for cryptocurrency payments.', 'Bitcoin-Zahlungen werden ueber unsere selbst gehostete BTCPay-Server-Instanz abgewickelt. Kein Drittanbieter-Zahlungsabwickler fuer Kryptowaehrungszahlungen.') ON CONFLICT (section, key) DO NOTHING;
INSERT INTO content_strings (id, section, key, value_en, value_de) VALUES (gen_random_uuid(), 'web', 'security.payment.btcpay.title', 'BTCPay Server (Self-Hosted)', 'BTCPay Server (selbst gehostet)') ON CONFLICT (section, key) DO NOTHING;
INSERT INTO content_strings (id, section, key, value_en, value_de) VALUES (gen_random_uuid(), 'web', 'security.payment.heading', 'Payment Security', 'Zahlungssicherheit') ON CONFLICT (section, key) DO NOTHING;
INSERT INTO content_strings (id, section, key, value_en, value_de) VALUES (gen_random_uuid(), 'web', 'security.payment.noPaymentData.description', 'We do not store credit card numbers, CVVs, or any payment credentials on our servers. All payment data is handled by Stripe or BTCPay Server.', 'Wir speichern keine Kreditkartennummern, CVVs oder Zahlungsdaten auf unseren Servern. Alle Zahlungsdaten werden von Stripe oder BTCPay Server verarbeitet.') ON CONFLICT (section, key) DO NOTHING;
INSERT INTO content_strings (id, section, key, value_en, value_de) VALUES (gen_random_uuid(), 'web', 'security.payment.noPaymentData.title', 'No Payment Data Stored', 'Keine Zahlungsdaten gespeichert') ON CONFLICT (section, key) DO NOTHING;
INSERT INTO content_strings (id, section, key, value_en, value_de) VALUES (gen_random_uuid(), 'web', 'security.payment.stripe.description', 'Credit card payments are processed by Stripe, a PCI DSS Level 1 certified payment processor. We never see or store your card details.', 'Kreditkartenzahlungen werden von Stripe, einem PCI DSS Level 1-zertifizierten Zahlungsabwickler, verarbeitet. Wir sehen oder speichern Ihre Kartendaten niemals.') ON CONFLICT (section, key) DO NOTHING;
INSERT INTO content_strings (id, section, key, value_en, value_de) VALUES (gen_random_uuid(), 'web', 'security.payment.stripe.title', 'Stripe (PCI DSS Compliant)', 'Stripe (PCI DSS-konform)') ON CONFLICT (section, key) DO NOTHING;
INSERT INTO content_strings (id, section, key, value_en, value_de) VALUES (gen_random_uuid(), 'web', 'security.principles.dataSovereignty.description', 'Your data belongs to you. Export it anytime as JSON or CSV. Delete your account and all data is removed within 30 days. We never lock you in.', 'Ihre Daten gehoeren Ihnen. Exportieren Sie sie jederzeit als JSON oder CSV. Loeschen Sie Ihr Konto und alle Daten werden innerhalb von 30 Tagen entfernt. Wir sperren Sie niemals ein.') ON CONFLICT (section, key) DO NOTHING;
INSERT INTO content_strings (id, section, key, value_en, value_de) VALUES (gen_random_uuid(), 'web', 'security.principles.dataSovereignty.title', 'Data Sovereignty', 'Datensouveraenitaet') ON CONFLICT (section, key) DO NOTHING;
INSERT INTO content_strings (id, section, key, value_en, value_de) VALUES (gen_random_uuid(), 'web', 'security.principles.heading', 'Our Security Principles', 'Unsere Sicherheitsprinzipien') ON CONFLICT (section, key) DO NOTHING;
INSERT INTO content_strings (id, section, key, value_en, value_de) VALUES (gen_random_uuid(), 'web', 'security.principles.minimalData.description', 'We collect only what is needed to provide the service: your email, your health measurements (encrypted), and your preferences. Nothing more.', 'Wir erfassen nur das, was fuer den Dienst benoetigt wird: Ihre E-Mail, Ihre Gesundheitsmessungen (verschluesselt) und Ihre Einstellungen. Nichts weiter.') ON CONFLICT (section, key) DO NOTHING;
INSERT INTO content_strings (id, section, key, value_en, value_de) VALUES (gen_random_uuid(), 'web', 'security.principles.minimalData.title', 'Minimal Data Collection', 'Minimale Datenerfassung') ON CONFLICT (section, key) DO NOTHING;
INSERT INTO content_strings (id, section, key, value_en, value_de) VALUES (gen_random_uuid(), 'web', 'security.principles.openSource.description', 'Our core technology is AGPL-3.0 licensed. Every line of code is publicly auditable. You do not have to trust our claims. You can verify them.', 'Unsere Kerntechnologie ist AGPL-3.0-lizenziert. Jede Zeile Code ist oeffentlich ueberpruefbar. Sie muessen unseren Aussagen nicht vertrauen. Sie koennen sie verifizieren.') ON CONFLICT (section, key) DO NOTHING;
INSERT INTO content_strings (id, section, key, value_en, value_de) VALUES (gen_random_uuid(), 'web', 'security.principles.openSource.title', 'Open Source', 'Open Source') ON CONFLICT (section, key) DO NOTHING;
INSERT INTO content_strings (id, section, key, value_en, value_de) VALUES (gen_random_uuid(), 'web', 'security.principles.privacyByDesign.description', 'No tracking, no profiling, no behavioral analytics. We do not monitor how you use the platform. We do not build user profiles for any purpose.', 'Kein Tracking, kein Profiling, keine Verhaltensanalysen. Wir ueberwachen nicht, wie Sie die Plattform nutzen. Wir erstellen keine Benutzerprofile fuer irgendeinen Zweck.') ON CONFLICT (section, key) DO NOTHING;
INSERT INTO content_strings (id, section, key, value_en, value_de) VALUES (gen_random_uuid(), 'web', 'security.principles.privacyByDesign.title', 'Privacy by Design', 'Privacy by Design') ON CONFLICT (section, key) DO NOTHING;
INSERT INTO content_strings (id, section, key, value_en, value_de) VALUES (gen_random_uuid(), 'web', 'security.technical.aes256.description', 'All health measurement values are encrypted using AES-256-GCM before being written to the database. The encryption key is stored separately from the database.', 'Alle Gesundheitsmesswerte werden mit AES-256-GCM verschluesselt, bevor sie in die Datenbank geschrieben werden. Der Verschluesselungsschluessel wird getrennt von der Datenbank gespeichert.') ON CONFLICT (section, key) DO NOTHING;
INSERT INTO content_strings (id, section, key, value_en, value_de) VALUES (gen_random_uuid(), 'web', 'security.technical.aes256.title', 'AES-256-GCM Encryption at Rest', 'AES-256-GCM-Verschluesselung im Ruhezustand') ON CONFLICT (section, key) DO NOTHING;
INSERT INTO content_strings (id, section, key, value_en, value_de) VALUES (gen_random_uuid(), 'web', 'security.technical.docker.description', 'The platform runs in isolated Docker containers with minimal attack surface. Each service (API, frontend, database) runs in its own container.', 'Die Plattform laeuft in isolierten Docker-Containern mit minimaler Angriffsflaeche. Jeder Dienst (API, Frontend, Datenbank) laeuft in einem eigenen Container.') ON CONFLICT (section, key) DO NOTHING;
INSERT INTO content_strings (id, section, key, value_en, value_de) VALUES (gen_random_uuid(), 'web', 'security.technical.docker.title', 'Containerized Deployment', 'Containerisierte Bereitstellung') ON CONFLICT (section, key) DO NOTHING;
INSERT INTO content_strings (id, section, key, value_en, value_de) VALUES (gen_random_uuid(), 'web', 'security.technical.heading', 'Technical Security', 'Technische Sicherheit') ON CONFLICT (section, key) DO NOTHING;
INSERT INTO content_strings (id, section, key, value_en, value_de) VALUES (gen_random_uuid(), 'web', 'security.technical.noAnalytics.description', 'No Google Analytics, no Plausible, no tracking pixels, no cookies (except one optional referral cookie). No browser fingerprinting. No device identifiers.', 'Kein Google Analytics, kein Plausible, keine Tracking-Pixel, keine Cookies (ausser einem optionalen Empfehlungs-Cookie). Kein Browser-Fingerprinting. Keine Geraetekennungen.') ON CONFLICT (section, key) DO NOTHING;
INSERT INTO content_strings (id, section, key, value_en, value_de) VALUES (gen_random_uuid(), 'web', 'security.technical.noAnalytics.title', 'No Third-Party Analytics', 'Keine Drittanbieter-Analytik') ON CONFLICT (section, key) DO NOTHING;
INSERT INTO content_strings (id, section, key, value_en, value_de) VALUES (gen_random_uuid(), 'web', 'security.technical.securityUpdates.description', 'Dependencies are kept up to date. The Rust backend provides memory safety guarantees. OWASP Top 10 protections are implemented throughout the stack.', 'Abhaengigkeiten werden aktuell gehalten. Das Rust-Backend bietet Speichersicherheitsgarantien. OWASP Top 10-Schutzmaßnahmen sind im gesamten Stack implementiert.') ON CONFLICT (section, key) DO NOTHING;
INSERT INTO content_strings (id, section, key, value_en, value_de) VALUES (gen_random_uuid(), 'web', 'security.technical.securityUpdates.title', 'Regular Security Updates', 'Regelmaessige Sicherheitsupdates') ON CONFLICT (section, key) DO NOTHING;
INSERT INTO content_strings (id, section, key, value_en, value_de) VALUES (gen_random_uuid(), 'web', 'security.technical.tls13.description', 'All communication between your browser and our servers uses TLS 1.3, the latest transport layer security protocol.', 'Die gesamte Kommunikation zwischen Ihrem Browser und unseren Servern verwendet TLS 1.3, das neueste Transport-Layer-Security-Protokoll.') ON CONFLICT (section, key) DO NOTHING;
INSERT INTO content_strings (id, section, key, value_en, value_de) VALUES (gen_random_uuid(), 'web', 'security.technical.tls13.title', 'TLS 1.3 Encryption in Transit', 'TLS 1.3-Verschluesselung bei der Uebertragung') ON CONFLICT (section, key) DO NOTHING;
INSERT INTO content_strings (id, section, key, value_en, value_de) VALUES (gen_random_uuid(), 'web', 'security.technical.zeroKnowledge.description', 'Platform administrators cannot read your health data. Even with full database access, measurement values remain encrypted and unreadable without the separate encryption key.', 'Plattform-Administratoren koennen Ihre Gesundheitsdaten nicht lesen. Selbst bei vollem Datenbankzugriff bleiben Messwerte verschluesselt und ohne den separaten Verschluesselungsschluessel unlesbar.') ON CONFLICT (section, key) DO NOTHING;
INSERT INTO content_strings (id, section, key, value_en, value_de) VALUES (gen_random_uuid(), 'web', 'security.technical.zeroKnowledge.title', 'Zero-Knowledge Architecture', 'Zero-Knowledge-Architektur') ON CONFLICT (section, key) DO NOTHING;
INSERT INTO content_strings (id, section, key, value_en, value_de) VALUES (gen_random_uuid(), 'web', 'terms.note', 'Legal document - English only', 'Rechtsdokument - nur auf Englisch') ON CONFLICT (section, key) DO NOTHING;
