-- Content strings table: stores next-intl static strings for admin editing
-- Separate from ui_strings/ui_string_translations (ContentProvider dynamic system)

CREATE TABLE IF NOT EXISTS content_strings (
    id UUID PRIMARY KEY DEFAULT gen_random_uuid(),
    section TEXT NOT NULL,         -- 'app', 'web', 'admin'
    key TEXT NOT NULL,             -- flattened dot-key e.g. 'common.loading'
    value_en TEXT NOT NULL,
    value_de TEXT,
    description TEXT,
    updated_at TIMESTAMPTZ DEFAULT now(),
    updated_by UUID REFERENCES users(id) ON DELETE SET NULL,
    UNIQUE(section, key)
);

CREATE INDEX IF NOT EXISTS idx_content_strings_section ON content_strings(section);

